-- -------------------------------------------------------------
-- View 5: v_master_products_full (Denormalized Unified View)
-- -------------------------------------------------------------
DROP VIEW IF EXISTS v_master_products_full;
CREATE VIEW v_master_products_full AS
SELECT 
    p.id,
    p.master_sku,
    p.original_sku,
    p.barcode_ean13,
    p.brand,
    p.model_name,
    c.category_name,
    c.category_group,
    p.hs_code,
    p.color,
    p.sizes_available,
    p.material_upper,
    p.material_outsole,
    p.steel_toe_cap,
    p.slip_resistance_rating,
    p.price_retail_avg_idr,
    p.price_wholesale_idr,
    p.price_fob_usd,
    p.pairs_per_carton,
    p.carton_volume_cbm,
    p.primary_image_url,
    p.primary_image_source,
    p.total_reference_images,
    cr.shopee_folder,
    cr.tokopedia_id,
    cr.blibli_id,
    cr.lazada_id,
    cr.alibaba_matrix_sku,
    p.description_id,
    p.description_en
FROM master_products p
JOIN master_categories c ON p.category_id = c.category_id
LEFT JOIN product_marketplace_crossref cr ON p.id = cr.product_id;
